import{_ as l,I as s,c as n,o as i,aG as r,j as t,J as o,a as p}from"./chunks/framework.Q0aKGMVe.js";const k=JSON.parse('{"title":"AI 订阅指南","description":"","frontmatter":{},"headers":[],"relativePath":"special/ai/buy.md","filePath":"special/ai/buy.md"}'),d={name:"special/ai/buy.md"};function h(c,e,b,u,m,f){const a=s("Badge");return i(),n("div",null,[e[4]||(e[4]=r('<h1 id="ai-订阅指南" tabindex="-1">AI 订阅指南 <a class="header-anchor" href="#ai-订阅指南" aria-label="Permalink to “AI 订阅指南”">​</a></h1><p>目前AI最强模型 ClaudeCode、Codex、Gemini 三家均对我国封锁，为师夷长技以制夷，简述购买使用方式，部分章节敏感词过多，请自行搜索关键词。</p><h1 id="购买" tabindex="-1">购买 <a class="header-anchor" href="#购买" aria-label="Permalink to “购买”">​</a></h1><p>目前基本有订阅和Api两种使用方式，订阅等同于包月付费，Api等同于按量付费。以 <code>claude</code>为例，订阅用量价格远远小于Api。</p><blockquote><p>参考来源： <a href="https://she-llac.com/claude-limits" target="_blank" rel="noreferrer">https://she-llac.com/claude-limits</a></p></blockquote><table tabindex="0"><thead><tr><th></th><th>订阅价格</th><th>用量换算为Api价格</th></tr></thead><tbody><tr><td>Pro</td><td>$20</td><td>$163</td></tr><tr><td>Max 5x</td><td>$100</td><td>$1354</td></tr><tr><td>Max 20x</td><td>$200</td><td>$2708</td></tr></tbody></table><p>但是订阅需要自行解决梯子、风控等问题，所以催生出了<code>中转站（二道贩子）</code>，以下Api均指中转站，而非官方Api。</p><p>两者使用区别如下：</p><blockquote><p>如果你能官方购买Api，那么你也能购买订阅。以下Api均以中转站为例。</p></blockquote><table tabindex="0"><thead><tr><th></th><th>订阅</th><th>Api（中转站）</th></tr></thead><tbody><tr><td>使用限制</td><td>每 5h 1w 有用量限制</td><td>无限制</td></tr><tr><td>何处使用</td><td>仅支持官方客户端</td><td>任意，如小龙虾或自研agent</td></tr><tr><td>增值服务</td><td>官方客户端支持额外功能，如： webSearch、电脑控制、浏览控制等</td><td>无</td></tr><tr><td>支付方式</td><td>境外信用卡、ApplePay，GooglePay</td><td>宽松，支付宝微信等</td></tr><tr><td>梯子</td><td>纯度高的固定IP</td><td>一般不需要</td></tr><tr><td>风险</td><td>账号被ban，kyc（境外版眨眼摇头）</td><td>大部分假模型，投毒偷数据</td></tr></tbody></table><p>总之订阅便宜功能多，只能在官方客户端使用且风控，Api无限制但鱼龙混杂假货多。</p><p>其中购买由难到易分别为：<code>Claude</code>、<code>Codex</code>、<code>Gemini</code>，以下以<code>Claude</code>为例，其他基本都差不多，分别说明两种的购买方式。</p><h2 id="订阅" tabindex="-1">订阅 <a class="header-anchor" href="#订阅" aria-label="Permalink to “订阅”">​</a></h2><h3 id="梯子" tabindex="-1">梯子 <a class="header-anchor" href="#梯子" aria-label="Permalink to “梯子”">​</a></h3><p>自行解决，最好是美西或新加坡ip，注意落地IP纯净，可以通过 <a href="https://ippure.com/" target="_blank" rel="noreferrer">ippure</a> 查看，实际体感并不追求家宽IP（有更好），只要不是万人骑的机场IP就行（如果你访问 Google 经常弹出校验，大概率不行）。尽量保证固定IP使用，避免频繁切换极易被风控。</p><blockquote><p>我使用的是<a href="https://www.dmit.io/aff.php?aff=14976" target="_blank" rel="noreferrer">DMIT</a>自建梯子，Premium(CN2-GIA)线路，三个月了目前正常。</p></blockquote><h3 id="注册" tabindex="-1">注册 <a class="header-anchor" href="#注册" aria-label="Permalink to “注册”">​</a></h3><p>优先推荐使用 Google 老号登录，大概率不需要手机号，如果被风控需要手机号登录，可以去接码平台找个临时手机号。</p>',18)),t("ul",null,[t("li",null,[o(a,{type:"tip",text:"免费"}),e[0]||(e[0]=p()),e[1]||(e[1]=t("a",{href:"https://www.freereceivesms.com/us/",target:"_blank",rel:"noreferrer"},"freereceivesms.com",-1))]),t("li",null,[o(a,{type:"danger",text:"付费"}),e[2]||(e[2]=p()),e[3]||(e[3]=t("a",{href:"https://hero-sms.com/?ref=1012473",target:"_blank",rel:"noreferrer"},"hero-sms.com",-1))])]),e[5]||(e[5]=r('<h3 id="支付方式" tabindex="-1">支付方式 <a class="header-anchor" href="#支付方式" aria-label="Permalink to “支付方式”">​</a></h3><blockquote><p>从易到难</p></blockquote><div class="warning custom-block"><p class="custom-block-title custom-block-title-default">WARNING</p><p>！！！若需要选择美国地区，应选择免税州：俄勒冈州 (Oregon)、特拉华州 (Delaware)、蒙大拿州 (Montana)、新罕布什尔州 (New Hampshire) 和阿拉斯加州 (Alaska)</p></div><p><strong>美区国付</strong></p><blockquote><p>感觉是 Apple 的 bug，不知道什么时候会修复</p><p>！！！此种方式购买 max 及以上套餐需要额外支付 $20 苹果税。</p><p>被 ban 退款到卡</p></blockquote><p>将 <code>AppleId</code>切换到美国，下载<code>Claude</code>登录后，切换 <code>AppleId</code>到国内，然后内购购买订阅，使用国内支付即可。</p><p><strong>ApplePay / GooglePay</strong></p><blockquote><p>！！！此种方式购买 max 及以上套餐需要额外支付 $20 苹果税。</p><p>被 ban 退款到卡</p></blockquote><p>切换到美区，使用国内外币信用卡绑定苹果或谷歌然后支付。</p><p><strong>Apple / Google 礼品卡</strong></p><blockquote><p>！！！此种方式购买 max 及以上套餐需要额外支付 $20 苹果税。</p><p>被 ban 退款到账户，黑卡锁号</p></blockquote><p>切换到美区，购买礼品卡充值到 Apple / Google 账户，然后购买订阅。</p><details class="details custom-block"><summary>支付宝就有美区礼品卡购买。</summary><ol><li><p><strong>切换支付宝定位</strong></p><p>打开支付宝，点击左上角的“定位”图标。选择“国际/港澳台”，然后选择“北美洲”，接着选择“美国”，最后选择一个具体的城市（如旧金山、拉斯维加斯等）</p></li><li><p><strong>进入 Pockyt Shop</strong></p><p>完成定位切换后，通常会在首页看到 Pockyt Shop 的入口。如果未显示，可以通过支付宝搜索栏直接输入“Pockyt Shop”并点击进入。</p></li><li><p><strong>购买美区礼品卡</strong></p><p>点击 App Store &amp; iTunes US 选项可自行输入需要充值的礼品卡金额，金额范围为 2~500。点击 Apple Gift Card US 选项则购买固定金额礼品卡。</p></li></ol></details><details class="details custom-block"><summary>尼区 6 折</summary><p>尼日利亚定价汇率低，约为美区 6 折。但大部分礼品卡为黑卡~</p></details><p><strong>境外卡直付</strong></p><p>使用 <code>n26``wise</code>等国内可申的境外卡直接官网支付，这种方式没有苹果税，但申请难度较大。</p><p>**代付 / 成品号 **</p><p>这个风险较大，就不具体推荐了。</p><h2 id="api" tabindex="-1">API <a class="header-anchor" href="#api" aria-label="Permalink to “API”">​</a></h2><p>中转站很多参水的，最简单测试有很多检测网站如：<a href="https://github.com/AetherCore-Dev/relay-radar" target="_blank" rel="noreferrer">relay-radar</a></p><p>下面仅介绍绝对靠谱的几个中转站。</p><blockquote><p>Api 方式部分工具需要额外付费， 如 web search</p></blockquote><p><a href="https://openrouter.ai/" target="_blank" rel="noreferrer"><strong>OpenRouter</strong></a></p><p>全球最大的中转站，模型保真，价格官网+5.5%，但是会透传用户网络信息，所以还是需要科学环境下使用。</p><p><a href="https://docs.cloud.google.com/vertex-ai/" target="_blank" rel="noreferrer"><strong>Vertex-ai</strong></a>** （Google） / <strong><a href="https://aws.amazon.com/cn/bedrock/pricing/" target="_blank" rel="noreferrer"><strong>aws</strong></a></strong> (亚马逊) / <strong><a href="https://azure.microsoft.com/en-us/pricing/details/microsoft-foundry/#pricing" target="_blank" rel="noreferrer"><strong>microsoft-foundry</strong></a></strong> / (微软)**</p><p>价格对比 <a href="https://platform.claude.com/docs/zh-CN/about-claude/pricing" target="_blank" rel="noreferrer">pricing</a></p><p><a href="https://zenmux.ai/invite/CT9D6D" target="_blank" rel="noreferrer"><strong>ZenMux</strong></a></p><blockquote><p>邀请码：CT9D6D 得 $5</p></blockquote><p>蚂蚁自家开的，支持SLA赔付，也支持 Api 和订阅购买。</p><h2 id="mix" tabindex="-1">Mix <a class="header-anchor" href="#mix" aria-label="Permalink to “Mix”">​</a></h2><p>既然订阅这么便宜，但需要稳定的IP。那我再服务器上跑 <code>Claude</code>然后通过 http 暴露 Api 不就能让 ip 一直固定且让其他软件也能使用了吗？</p><p>of course 靓仔，恭喜你发明了中转站。当然各厂商也想到了，<strong>所以被抓的后果是直接封号</strong>。</p><p>本地使用： <a href="https://github.com/router-for-me/CLIProxyAPI" target="_blank" rel="noreferrer">CLIProxyAPI</a> / 多人使用：<a href="https://github.com/Wei-Shaw/sub2api" target="_blank" rel="noreferrer">sub2api</a></p><h1 id="使用" tabindex="-1">使用 <a class="header-anchor" href="#使用" aria-label="Permalink to “使用”">​</a></h1><h2 id="自家使用" tabindex="-1">自家使用 <a class="header-anchor" href="#自家使用" aria-label="Permalink to “自家使用”">​</a></h2><p>可以通过 <a href="https://ip.skk.moe/split-tunnel" target="_blank" rel="noreferrer">https://ip.skk.moe/split-tunnel</a> 测试网络情况。</p><h3 id="本机proxy模式" tabindex="-1">本机proxy模式 <a class="header-anchor" href="#本机proxy模式" aria-label="Permalink to “本机proxy模式”">​</a></h3><p>开启梯子的 socks5 +http 代理模式，设置全局代理</p><div class="language-plain"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>export http_proxy=&quot;socks5://127.0.0.1:7890&quot;</span></span>\n<span class="line"><span>export https_proxy=&quot;socks5://127.0.0.1:7890&quot;</span></span>\n<span class="line"><span>export all_proxy=&quot;socks5://127.0.0.1:7890&quot;   # 可选，全局兜底</span></span></code></pre></div><p><strong>注意：</strong>系统代理对于软件来说只是可选项，并不是开启系统代理===全局代理，如<code>Claude Desktop</code>和大部分 GUI 软件均不受系统代理影响（你开发软件有考虑支持用户代理网络么... =.=），而且 proxy 模式对 udp 流量支持也不好，也会有 DNS 泄露等问题。</p><h3 id="本机tun模式" tabindex="-1">本机tun模式 <a class="header-anchor" href="#本机tun模式" aria-label="Permalink to “本机tun模式”">​</a></h3><p>开启代理软件中的 tun 模式，相当于在本机新建一个虚拟网卡，接管设备上所有网络流量交给梯子软件分流，就可以避免软件不支持代理的情况。但同时也会带来额外的性能开销，多VPN环境下路由表冲突。</p><h3 id="本机应用透明代理" tabindex="-1">本机应用透明代理 <a class="header-anchor" href="#本机应用透明代理" aria-label="Permalink to “本机应用透明代理”">​</a></h3><p>我们还可以通过软件来接管其他软件的网络，windows 可以通过 <a href="https://www.proxifier.com/" target="_blank" rel="noreferrer">Proxifier </a> ，MacOS 可以通过 <a href="https://antifyapp.com/zh/" target="_blank" rel="noreferrer">Antify</a> ，可以让不支持代理的应用也能通过代理连接网络。</p><h3 id="软路由" tabindex="-1">软路由 <a class="header-anchor" href="#软路由" aria-label="Permalink to “软路由”">​</a></h3><p>将梯子架在路由器上，即可实现整个局域网的透明代理，无需关心设备是否支持。</p><p>梯子其实就是封包解包、加解密，纯纯的cpu密集运算，路由的硬件加速等均会失效（可以通过路由表将国内直连绕过梯子处理）。所以一个强大的cpu是必备的，SOC 性能可以参考 <a href="https://mao.fan/socpk.html" target="_blank" rel="noreferrer">https://mao.fan/socpk.html</a>，固件选择 <a href="https://firmware-selector.immortalwrt.org/" target="_blank" rel="noreferrer">openwrt-ImmortalWrt</a> 就行了，联发科兼容性较好。</p><p>咸鱼￥80可以买到 IPQ6000，大约可以支撑 200 Mbps 左右梯子带宽。</p>',48))])}const x=l(d,[["render",h]]);export{k as __pageData,x as default};
